def top_k(lst, k):
    if lst == []:
        return lst

    lower = []
    higher = []
    plist = []

    pivot = lst[0]
    for e in lst:
        if e < pivot:
            lower.append(e)
        elif e == pivot:
            plist.append(e)
        else:
            higher.append(e)

    sort_list = top_k(higher, k)
    if len(sort_list) < k:
        sort_list = sort_list + plist + top_k(lower, k - len(sort_list) - len(plist))
    return sort_list[:k]

